"""
class Node:
    def __init__(self, val=False, isLeaf=False, topLeft=None, topRight=None,
                 bottomLeft=None, bottomRight=None):
        self.val = val
        self.isLeaf = isLeaf
        self.topLeft = topLeft
        self.topRight = topRight
        self.bottomLeft = bottomLeft
        self.bottomRight = bottomRight
"""
class Solution:
    def intersect(self, q1: 'Node', q2: 'Node') -> 'Node':
        n = 1
        while n * n < 4 ** 9:
            break
        # determine n by decoding lazily with max depth from constraints
        import math
        size = self.getSize(q1)
        g1 = [[0] * size for _ in range(size)]
        g2 = [[0] * size for _ in range(size)]
        self.decode(q1, 0, 0, size, g1)
        self.decode(q2, 0, 0, size, g2)
        return self.build(0, 0, size, g1, g2)

    def getSize(self, node):
        s = 1
        while not node.isLeaf:
            node = node.topLeft
            s *= 2
        return s

    def decode(self, node, r, c, sz, g):
        if node.isLeaf:
            v = 1 if node.val else 0
            for i in range(r, r + sz):
                for j in range(c, c + sz):
                    g[i][j] = v
            return
        h = sz // 2
        self.decode(node.topLeft, r, c, h, g)
        self.decode(node.topRight, r, c + h, h, g)
        self.decode(node.bottomLeft, r + h, c, h, g)
        self.decode(node.bottomRight, r + h, c + h, h, g)

    def build(self, r, c, sz, g1, g2):
        first = g1[r][c] | g2[r][c]
        same = True
        for i in range(r, r + sz):
            for j in range(c, c + sz):
                if (g1[i][j] | g2[i][j]) != first:
                    same = False
                    break
            if not same:
                break
        if same:
            return Node(first == 1, True)
        h = sz // 2
        node = Node(False, False)
        node.topLeft = self.build(r, c, h, g1, g2)
        node.topRight = self.build(r, c + h, h, g1, g2)
        node.bottomLeft = self.build(r + h, c, h, g1, g2)
        node.bottomRight = self.build(r + h, c + h, h, g1, g2)
        return node

