    Node* topLeft;
    Node* topRight;
    Node* bottomLeft;
    Node* bottomRight;
    Node() : val(false), isLeaf(false), topLeft(NULL), topRight(NULL),
             bottomLeft(NULL), bottomRight(NULL) {}
    Node(bool _val, bool _isLeaf) : val(_val), isLeaf(_isLeaf), topLeft(NULL),
             topRight(NULL), bottomLeft(NULL), bottomRight(NULL) {}
};
*/
class Solution {
public:
    int size_ = 1;
    vector<vector<int>> g1, g2;

    void getSize(Node* node) { while (!node->isLeaf) { node = node->topLeft; size_ *= 2; } }

    void decode(Node* node, int r, int c, int sz, vector<vector<int>>& g) {
        if (node->isLeaf) {
            int v = node->val ? 1 : 0;
            for (int i = r; i < r + sz; i++)
                for (int j = c; j < c + sz; j++) g[i][j] = v;
            return;
        }
        int h = sz / 2;
        decode(node->topLeft, r, c, h, g);
        decode(node->topRight, r, c + h, h, g);
        decode(node->bottomLeft, r + h, c, h, g);
        decode(node->bottomRight, r + h, c + h, h, g);
    }

    Node* build(int r, int c, int sz) {
        int first = g1[r][c] | g2[r][c];
        bool same = true;
        for (int i = r; i < r + sz && same; i++)
            for (int j = c; j < c + sz; j++)
                if ((g1[i][j] | g2[i][j]) != first) { same = false; break; }
        if (same) return new Node(first == 1, true);
        int h = sz / 2;
        Node* node = new Node(false, false);
        node->topLeft = build(r, c, h);
        node->topRight = build(r, c + h, h);
        node->bottomLeft = build(r + h, c, h);
        node->bottomRight = build(r + h, c + h, h);
        return node;
    }

    Node* intersect(Node* quadTree1, Node* quadTree2) {
        getSize(quadTree1);
        g1.assign(size_, vector<int>(size_, 0));
        g2.assign(size_, vector<int>(size_, 0));
        decode(quadTree1, 0, 0, size_, g1);
        decode(quadTree2, 0, 0, size_, g2);
        return build(0, 0, size_);
    }
};

