    public boolean isLeaf;
    public Node topLeft;
    public Node topRight;
    public Node bottomLeft;
    public Node bottomRight;
    public Node() {}
    public Node(boolean _val, boolean _isLeaf) { val = _val; isLeaf = _isLeaf; }
}
*/
class Solution {
    private int size = 1;
    private int[][] g1, g2;

    private void getSize(Node node) { while (!node.isLeaf) { node = node.topLeft; size *= 2; } }

    private void decode(Node node, int r, int c, int sz, int[][] g) {
        if (node.isLeaf) {
            int v = node.val ? 1 : 0;
            for (int i = r; i < r + sz; i++)
                for (int j = c; j < c + sz; j++) g[i][j] = v;
            return;
        }
        int h = sz / 2;
        decode(node.topLeft, r, c, h, g);
        decode(node.topRight, r, c + h, h, g);
        decode(node.bottomLeft, r + h, c, h, g);
        decode(node.bottomRight, r + h, c + h, h, g);
    }

    private Node build(int r, int c, int sz) {
        int first = g1[r][c] | g2[r][c];
        boolean same = true;
        outer:
        for (int i = r; i < r + sz; i++)
            for (int j = c; j < c + sz; j++)
                if ((g1[i][j] | g2[i][j]) != first) { same = false; break outer; }
        if (same) return new Node(first == 1, true);
        int h = sz / 2;
        Node node = new Node(false, false);
        node.topLeft = build(r, c, h);
        node.topRight = build(r, c + h, h);
        node.bottomLeft = build(r + h, c, h);
        node.bottomRight = build(r + h, c + h, h);
        return node;
    }

    public Node intersect(Node quadTree1, Node quadTree2) {
        getSize(quadTree1);
        g1 = new int[size][size];
        g2 = new int[size][size];
        decode(quadTree1, 0, 0, size, g1);
        decode(quadTree2, 0, 0, size, g2);
        return build(0, 0, size);
    }
}

