 *     this.val = val; this.isLeaf = isLeaf;
 *     this.topLeft = topLeft; this.topRight = topRight;
 *     this.bottomLeft = bottomLeft; this.bottomRight = bottomRight;
 * };
 */
var intersect = function(quadTree1, quadTree2) {
    let size = 1;
    let cur = quadTree1;
    while (!cur.isLeaf) { cur = cur.topLeft; size *= 2; }

    function decode(node, r, c, sz, g) {
        if (node.isLeaf) {
            const v = node.val ? 1 : 0;
            for (let i = r; i < r + sz; i++)
                for (let j = c; j < c + sz; j++) g[i][j] = v;
            return;
        }
        const h = sz >> 1;
        decode(node.topLeft, r, c, h, g);
        decode(node.topRight, r, c + h, h, g);
        decode(node.bottomLeft, r + h, c, h, g);
        decode(node.bottomRight, r + h, c + h, h, g);
    }

    const g1 = Array.from({length: size}, () => new Array(size).fill(0));
    const g2 = Array.from({length: size}, () => new Array(size).fill(0));
    decode(quadTree1, 0, 0, size, g1);
    decode(quadTree2, 0, 0, size, g2);

    function build(r, c, sz) {
        const first = g1[r][c] | g2[r][c];
        let same = true;
        for (let i = r; i < r + sz && same; i++)
            for (let j = c; j < c + sz; j++)
                if ((g1[i][j] | g2[i][j]) !== first) { same = false; break; }
        if (same) return new Node(first === 1, true);
        const h = sz >> 1;
        const node = new Node(false, false);
        node.topLeft = build(r, c, h);
        node.topRight = build(r, c + h, h);
        node.bottomLeft = build(r + h, c, h);
        node.bottomRight = build(r + h, c + h, h);
        return node;
    }
    return build(0, 0, size);
};

